package in.recallradar;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
enum MovementType { RECEIPT, TRANSFER, ADJUSTMENT, WASTE, DISPOSAL, PRODUCTION_CONSUMPTION }
@Entity @Table(name="inventory_lot",uniqueConstraints=@UniqueConstraint(columnNames={"organizationId","supplierId","supplierBatchNumber"})) class InventoryLot { @Id UUID id; @Version Long version; UUID organizationId; UUID ingredientId; UUID supplierId; String supplierBatchNumber; LocalDate manufactureDate; LocalDate expiryDate; String unit; Instant receivedAt; Instant createdAt; protected InventoryLot(){} InventoryLot(UUID org,UUID ingredient,UUID supplier,String batch,LocalDate made,LocalDate expiry,String unit){id=UUID.randomUUID();organizationId=org;ingredientId=ingredient;supplierId=supplier;supplierBatchNumber=batch;manufactureDate=made;expiryDate=expiry;this.unit=unit;receivedAt=Instant.now();createdAt=Instant.now();} }
@Entity @Table(name="stock_movement") class StockMovement { @Id UUID id; UUID organizationId; UUID lotId; UUID fromLocationId; UUID toLocationId; @Enumerated(EnumType.STRING) MovementType movementType; BigDecimal quantity; Instant occurredAt; String note; protected StockMovement(){} StockMovement(UUID org,UUID lot,UUID from,UUID to,MovementType type,BigDecimal quantity,String note){id=UUID.randomUUID();organizationId=org;lotId=lot;fromLocationId=from;toLocationId=to;movementType=type;this.quantity=quantity;this.note=note;occurredAt=Instant.now();} }
@Entity @Table(name="inventory_balance",uniqueConstraints=@UniqueConstraint(columnNames={"lotId","locationId"})) class InventoryBalance { @Id UUID id; UUID organizationId; UUID lotId; UUID locationId; BigDecimal quantity; @Version Long version; Instant updatedAt; protected InventoryBalance(){} InventoryBalance(UUID organizationId,UUID lotId,UUID locationId,BigDecimal quantity){id=UUID.randomUUID();this.organizationId=organizationId;this.lotId=lotId;this.locationId=locationId;this.quantity=quantity;updatedAt=Instant.now();} void add(BigDecimal delta){quantity=quantity.add(delta);updatedAt=Instant.now();} }
@Entity @Table(name="inventory_command",uniqueConstraints=@UniqueConstraint(columnNames={"organizationId","actorId","idempotencyKey"})) class InventoryCommand { @Id UUID id; UUID organizationId; UUID actorId; String idempotencyKey; String operation; UUID lotId; Instant createdAt; protected InventoryCommand(){} InventoryCommand(UUID organizationId,UUID actorId,String idempotencyKey,String operation,UUID lotId){id=UUID.randomUUID();this.organizationId=organizationId;this.actorId=actorId;this.idempotencyKey=idempotencyKey;this.operation=operation;this.lotId=lotId;createdAt=Instant.now();} }
